def transform(grid):
    out = [row[:] for row in grid]
    row_starts = [0, 4, 8]
    col_starts = [0, 7]
    panel_h, panel_w = 3, 6

    # Locate the panel containing the pattern rather than the plain background.
    source = None
    for rs in row_starts:
        for cs in col_starts:
            cells = [grid[r][c] for r in range(rs, rs + panel_h)
                     for c in range(cs, cs + panel_w)]
            counts = {}
            for v in cells:
                counts[v] = counts.get(v, 0) + 1
            bg = max(counts, key=counts.get)
            if any(v != bg for v in cells):
                source = [[grid[rs + i][cs + j] for j in range(panel_w)]
                          for i in range(panel_h)]
                break
        if source is not None:
            break

    if source is None:
        return out

    for rs in row_starts:
        for cs in col_starts:
            for i in range(panel_h):
                for j in range(panel_w):
                    out[rs + i][cs + j] = source[i][j]
    return out
